CREATE TABLE sku_materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by text NOT NULL, sku_id uuid NOT NULL REFERENCES skus(id) ON DELETE CASCADE, material_id uuid NOT NULL REFERENCES materials(id) ON DELETE CASCADE, qty_per_unit numeric(12,4) NOT NULL DEFAULT 0, waste_pct numeric(7,3) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by, sku_id, material_id))